    1192 server/cli/convo.ts
/**
 * convo — CLI for the workstation decision hub.
 *
 * Thin wrapper over the SAME store service the HTTP server uses, so creation,
 * status recomputation, zod validation, and atomic writes are identical to a
 * PUT through the API. No protocol logic is duplicated here.
 *
 * Usage (run via `bun run convo <cmd>`):
 *   convo create    <project-slug> <file.json | ->  # author a conversation
 *   convo add-item  <project-slug> <id> <item.json | -> # append item(s) to an
 *                                                   # EXISTING conversation
 *   convo read      <project-slug> <id>             # compact summary of answers
 *   convo list      <project-slug>                  # one line per conversation
 *   convo followups [project-slug]                  # conversations awaiting Claude
 *   convo handled   <project-slug> <id>             # mark a followup as handled
 *   convo watch     <project-slug> <id> [--timeout <minutes>]
 *                                                   # block until completed
 *
 * `create` refuses to clobber an existing conversation (which may hold user
 * answers) unless --force is passed. `-` reads the JSON payload from stdin.
 *
 * `add-item` is the APPEND-ONLY counterpart to `create --force`: `create`
 * rewrites the WHOLE conversation body, so the identity guard rejects it the
 * moment the conversation already holds a human response (correctly — the
 * agent must never re-author an answer). `add-item` instead reads the
 * conversation already on disk, runs the identity guard against ONLY the
 * new item(s) being appended, and writes back `existing.items` unchanged plus
 * the new tail — so a conversation full of human answers can still receive a
 * new agent-authored question/note/approval without those answers ever
 * passing back through the guard (or being re-serialized with different
 * values).
 *
 * Followup loop: when the user completes a conversation, the server flips
 * `agentFollowupStatus` to 'pending'. `followups` lists those; once Claude has
 * re-read the answers and acted on them, `handled` flips it to 'handled'.
 * That 'handled' flag is itself sticky (see `add-item` above): if `add-item`
 * later appends a fresh, unanswered item to an already-`handled`
 * conversation, `saveConversation` (server/services/conversationStore.ts)
 * detects the newly-introduced item id and resets `agentFollowupStatus` back
 * to 'none' — otherwise the leftover 'handled' would make `wakeReason` below
 * report the reopened conversation as already closed.
 *
 * Wake-up loop: `watch` BLOCKS (read-only, no lock) until the conversation is
 * genuinely 'completed', then exits 0 — a Claude session launches it in the
 * background right after `create` so the harness re-invokes the session when
 * the user has answered, with zero LLM polling.
 *
 * `status === 'completed'` is the primary done signal: the store
 * (saveConversation) recomputes it fresh from every item on every save, so it
 * can never be stale — EXCEPT that `saveConversation` deliberately preserves
 * a manually-set `status: 'archived'` even once every item has been answered
 * (`computeStatus` would say 'completed'). So `status` alone under-reports
 * completion for an archived conversation.
 *
 * `agentFollowupStatus === 'pending'` looks like a fix for that, but it is
 * STICKY — the store only ever sets it to 'pending' in the same save that
 * `computeStatus` yields 'completed', and only clears it via an explicit
 * `convo handled` — so on its own it cannot tell a FRESH completion from a
 * LEFTOVER one still sitting there from an earlier, never-`handled` round.
 * An earlier design compared it to a baseline captured at `watch` start, but
 * that is fooled by two different races: (a) two saves close enough together
 * that a coalesced fs event lets `check()` observe only the LAST one — e.g.
 * completion immediately followed by a reopen (`add-item` appending a fresh
 * unanswered item) — leaves `agentFollowupStatus` reading 'pending' with
 * nothing genuinely new to report; (b) an archived conversation whose
 * `agentFollowupStatus` was ALREADY 'pending' at the baseline (a prior round
 * never `handled`) never shows a baseline-relative transition even when a
 * real new completion happens while `status` stays 'archived'.
 *
 * Both races share one root cause: leaning on a STICKY field for a decision
 * that must be correct on every independent snapshot. The fix instead
 * re-derives true completion directly from `items` via the same
 * `computeStatus` the store itself uses — a PURE function of the current
 * snapshot, never stale, never sticky, no baseline needed. `wakeReason`
 * checks `status === 'completed'` first (exact parity with `computeStatus`
 * for a non-archived conversation), then falls back to
 * `computeStatus(items) === 'completed'` to catch the archived case — which,
 * being freshly recomputed on every poll, is immune to both races above: a
 * reopened conversation always has an unanswered item so it never returns
 * 'completed', and a genuinely-newly-completed archived conversation always
 * does, regardless of what `agentFollowupStatus` happened to read before.
 * A third, independent closing signal exists beyond both checks above: the
 * second-brain bridge's raccord A (RA-AC-18) can resolve a conversation from
 * OUTSIDE the hub (e.g. the app), but its identity guard
 * (server/services/identityGuard.ts) forbids that write path from ever
 * setting an item `response` — so `status` stays 'pending'/'in_progress'
 * forever and `computeStatus(items)` never reads 'completed' for such a
 * conversation. `agentFollowupStatus === 'handled'` is the one signal that
 * path IS allowed to set (see `isConversationOpen`,
 * src/types/conversation.ts, the repo's single source of truth for "does
 * this conversation still need human attention" — it treats this same flag
 * value as closing, independent of `status`/`items`). `wakeReason` checks it
 * as a third branch so a conversation closed this way wakes `watch`
 * immediately instead of running out its full timeout.
 *
 * A fourth, final closing signal mirrors `isConversationOpen`'s remaining
 * clause: `status === 'archived'` is UNCONDITIONAL there, independent of item
 * completion — the dashboard's "Archiver" action can be used on a
 * conversation with items still unanswered, and `saveConversation` preserves
 * that manual `status: 'archived'` verbatim regardless of what
 * `computeStatus(items)` would say. `wakeReason` checks it last, after the
 * three checks above, so an archived-but-incomplete conversation still wakes
 * `watch` (VERDICT: ARCHIVED) instead of running out the full timeout on a
 * conversation the rest of the app already treats as closed.
 *
 * Exit codes: 0 answered (VERDICT: COMPLETED, VERDICT: FOLLOWUP_PENDING,
 * VERDICT: CLOSED_EXTERNALLY, or VERDICT: ARCHIVED), 1 missing/deleted file,
 * 2 timeout (default 120 min).
 */
import { promises as fs, watch, type FSWatcher } from 'node:fs';
import path from 'node:path';
import {
  ConversationSchema,
  ItemSchema,
  ApprovalDecisionSchema,
  computeStatus,
  type Conversation,
  type Item,
} from '../../src/types/conversation';
import { dataDir } from '../config';
import {
  getConversation,
  saveConversation,
  saveFailureReason,
  listConversations,
  findPendingFollowups,
  stampConversationOrigin,
} from '../services/conversationStore';
import { isSafeSegment } from '../services/slug';
import { checkConversationWrite } from '../services/identityGuard';
import { isHelpRequest, printUsage, subcommandHelp, fail, parseOriginFlag, parseSinceDaysFlag } from './cliUsage';
import { verifyMirrorResolution } from './convoMirrorSelfVerify';
import { resolveAgentOrigin, readGitBranch, createdByFromOrigin } from '../lib/agentOrigin';
import { AgentOriginSchema, type AgentOrigin } from '../../src/types/agentOrigin';
import { backfillOrigins, type BackfillRecord } from '../services/agentSessions/backfill';

async function readStdin(): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString('utf8');
}

function renderResponse(item: Item): string {
  const r = item.response as Record<string, unknown> | undefined;
  if (item.status !== 'answered' || !r) {
    if (item.kind === 'note') return item.requiresAck ? '(ack required, pending)' : '(info)';
    return '(pending)';
  }
  switch (item.kind) {
    case 'decision': {
      const ids = (r.selectedOptionIds as string[] | undefined) ?? [];
      const labels = ids.map(
        (id) => item.options.find((o) => o.id === id)?.label ?? id,
      );
      const custom = r.customText ? ` + “${String(r.customText)}”` : '';
      return (labels.join(', ') || '(none)') + custom;
    }
    case 'checklist': {
      const ids = (r.checkedIds as string[] | undefined) ?? [];
      return ids.length ? ids.join(', ') : '(none checked)';
    }
    case 'approval':
      return String(r.decision ?? '(?)');
    case 'proposal':
      return String(r.verdict ?? '(?)');
    case 'question':
      return String(r.text ?? '');
    case 'rating':
      return String(r.value ?? '');
    case 'note':
      return '(acknowledged)';
    case 'reminder':
      return '(fait)';
    case 'secret_request': {
      const fps = Object.entries((r.fingerprints as Record<string, string> | undefined) ?? {})
        .map(([k, v]) => `${k}=${v}`)
        .join(', ');
      const echeance = r.revokedAt
        ? 'RÉVOQUÉ'
        : r.expiresAt
          ? `expire ${String(r.expiresAt)}`
          : '';
      return (
        `livré → ${String(r.deliveredTo ?? '(?)')}` +
        (fps ? ` (empreintes: ${fps})` : '') +
        (echeance ? ` ${echeance}` : '')
      );
    }
    default:
      return JSON.stringify(r);
  }
}

function countsTowardCompletion(it: Item): boolean {
  return !(it.kind === 'note' && it.requiresAck !== true);
}

/* -------------------------------------------------------------------------- */
/*  Schema-error rendering                                                    */
/* -------------------------------------------------------------------------- */

/**
 * The subset of a zod issue we rely on, kept structural (no `import type
 * { ZodIssue }`) so this stays agnostic of the exact zod version's internal
 * issue shape. `path` is typed as `PropertyKey[]` (zod's real type) rather
 * than narrowed to `(string | number)[]` — we only ever compare its elements
 * with `typeof x === 'number'` or stringify them via `String()`, both of
 * which are safe for a stray symbol too.
 */
type SchemaIssue = { path: readonly PropertyKey[]; message: string; code: string };
type SchemaErrorLike = { issues: readonly SchemaIssue[] };

/**
 * Raw (pre-validation) id/kind of one item, resolved from the UNVALIDATED
 * payload — once `safeParse` has failed we can no longer trust `.data`, so
 * this reads straight off the JSON the caller sent. Falls back to a
 * positional label when even `id`/`kind` is itself missing/malformed, which
 * is common: a badly-shaped item is exactly the case most likely to also be
 * missing its `id`.
 */
function describeRawItem(rawItem: unknown, positionalFallback: string): { id: string; kind: string } {
  const obj = rawItem as Record<string, unknown> | undefined;
  const id = typeof obj?.id === 'string' && obj.id ? obj.id : positionalFallback;
  const kind = typeof obj?.kind === 'string' && obj.kind ? obj.kind : '(kind manquant)';
  return { id, kind };
}

/**
 * The single most common actionable-item mistake seen in practice
 * (2026-08-15 friction, `checklist` item written with an `items` array
 * instead of `options`; the same confusion applies to `decision`): the kind
 * word suggests "items", but every choice/checkbox kind (`decision`,
 * `checklist`) stores its entries in `options`
 * (`OptionSchema = {id, label, description?, recommended?}`,
 * src/types/conversation.ts). Points at a real, present template file for
 * that kind when one exists in templates/conversations/.
 */
function optionsHint(kind: string): string {
  const templateByKind: Record<string, string> = {
    decision: 'decision-architecture.json',
    checklist: 'checklist.json',
  };
  const templateFile = templateByKind[kind] ?? `${kind}.json`;
  return (
    `attendu : "options": [{ id, label, description?, recommended? }] (au moins 1 entrée) — ` +
    `PAS "items", qui n'existe sur aucun kind d'item. Voir templates/conversations/${templateFile} ` +
    `et src/types/conversation.ts.`
  );
}

/** Renders one zod issue against a known item's raw id/kind, with the
 * `options` hint appended when it applies. */
function formatItemIssue(
  id: string,
  kind: string,
  fieldPath: readonly PropertyKey[],
  issue: SchemaIssue,
): string {
  const field = fieldPath.length ? fieldPath.map(String).join('.') : '(item)';
  let line = `  - item ${id} (kind: ${kind}) — champ "${field}": ${issue.message}`;
  if (field === 'options' && issue.code === 'invalid_type') {
    line += `\n      ${optionsHint(kind)}`;
  }
  return line;
}

/**
 * Human-readable rendering of a `ConversationSchema` validation failure, used
 * in place of the raw `error.format()` dump. The raw zod tree buries the
 * failing item behind a numeric array index (`items.4.options`) and forces a
 * detour through src/types/conversation.ts just to know which item that is
 * and what shape it wanted — this walks `error.issues` instead and, for any
 * issue under `items[<n>]`, resolves `<n>` back to that item's real `id` and
 * `kind` so the message names the culprit directly. Improves READABILITY
 * only: every issue zod reported is still printed, nothing is summarized
 * away or suppressed, and the caller still gets `BLOCKED:` + exit 1.
 */
function describeConversationSchemaError(
  rawObj: Record<string, unknown>,
  error: SchemaErrorLike,
): string {
  const rawItems = Array.isArray(rawObj.items) ? (rawObj.items as unknown[]) : [];
  return error.issues
    .map((issue) => {
      const [root, idx, ...rest] = issue.path;
      if (root === 'items' && typeof idx === 'number') {
        const { id, kind } = describeRawItem(rawItems[idx], `#${idx}`);
        return formatItemIssue(id, kind, rest, issue);
      }
      const field = issue.path.length ? issue.path.map(String).join('.') : '(racine)';
      return `  - champ "${field}": ${issue.message}`;
    })
    .join('\n');
}

/** Same rendering as `describeConversationSchemaError`, for `add-item`'s
 * single-`Item` validation — there `issue.path` is already relative to the
 * item itself (no `items[<n>]` prefix to strip), so the raw item's id/kind
 * is read directly rather than resolved through an index. */
function describeItemSchemaError(rawItem: unknown, error: SchemaErrorLike): string {
  const { id, kind } = describeRawItem(rawItem, '(item)');
  return error.issues.map((issue) => formatItemIssue(id, kind, issue.path, issue)).join('\n');
}

const SCHEMA_SOURCE_HINT =
  'Gabarits prêts à copier : templates/conversations/*.json — schéma faisant foi : src/types/conversation.ts.';

async function cmdCreate(
  slug: string,
  source: string,
  force: boolean,
  allowSecretLike: boolean,
  originOverride?: Partial<AgentOrigin>,
) {
  if (!isSafeSegment(slug)) fail(`unsafe project slug "${slug}"`);
  const raw = source === '-' ? await readStdin() : await fs.readFile(source, 'utf8');

  let json: unknown;
  try {
    json = JSON.parse(raw);
  } catch (err) {
    fail(`payload is not valid JSON — ${(err as Error).message}`);
  }

  // Fill server-managed fields the schema requires, so callers can hand us a
  // minimal item list. saveConversation recomputes status/updatedAt anyway.
  const now = new Date().toISOString();
  const obj = json as Record<string, unknown>;
  obj.schemaVersion ??= 1;
  obj.status ??= 'pending';
  obj.createdAt ??= now;
  obj.updatedAt ??= now;
  // D2/D3 (chantier « provenance de session », lot 2): derive a real
  // AgentOrigin instead of a naked `createdBy` default (was 'claude') — env-based
  // detection (Claude/Codex session env vars) unless `--origin-json`
  // explicitly overrides it. `createdByFromOrigin` then derives the legacy
  // `createdBy` enum FROM that origin, falling back to 'claude' only when
  // the origin itself is genuinely unresolvable (see its own doc comment) —
  // preserving this call site's historical default for that one case.
  //
  // ALWAYS re-resolve — never `??=`-skip when the payload already carries an
  // `origin` (P1, revue adversariale du 2026-09-08). The `??=` form persisted
  // a caller-supplied origin VERBATIM, and the payload of a `convo create` is
  // routinely a file the agent did not author: `templates/conversations/*.json`
  // is exactly what CLAUDE.md points agents at ("Modèles prêts à copier"), and
  // a template saved from the dashboard carries an `origin` of its own. Skipping
  // the resolver there stamped an agent-created conversation with whatever that
  // file happened to hold — at a rank the hook (3) and the backfill (1) can
  // never take back. The MCP twin already decided this the other way and says
  // so in its own comment (`server/mcp/hubWriteTools.ts`, `convo_create`):
  // re-resolve every time, and feed the caller's origin in as `explicit` input
  // (shape-validated, never trusted verbatim) rather than as the answer.
  //
  // Priority for the resolver's `explicit` input: the `--origin-json` flag
  // (this command's own argument, the most deliberate signal) > a
  // payload-supplied `origin` > plain env detection.
  //
  // P2 fix (constat 2, revue adversariale): a payload-supplied `origin` is
  // only trusted when its `runtime` is an AGENT runtime ('claude'/'codex').
  // `templates/conversations/*.json` — exactly what CLAUDE.md points agents
  // at — historically carried `origin.runtime:'user'`/`'claude-ai'` from
  // whoever last saved that template from the dashboard/claude.ai; letting
  // that survive into `explicit` here would have `resolveAgentOrigin`
  // stamp the copying AGENT's own conversation as authored by a human/
  // remote session it never was, at a rank the hook/backfill repair paths
  // can never take back. A non-agent runtime coming from the FILE is
  // dropped (falls through to env detection below) — `--origin-json` (this
  // command's own flag, a deliberate operator signal, never a copied file)
  // is NOT filtered: `originOverride` still wins outright via `??`.
  const payloadOrigin = AgentOriginSchema.partial().safeParse(obj.origin);
  const AGENT_RUNTIMES_ONLY = new Set(['claude', 'codex']);
  const trustedPayloadOrigin =
    payloadOrigin.success && (!payloadOrigin.data.runtime || AGENT_RUNTIMES_ONLY.has(payloadOrigin.data.runtime))
      ? payloadOrigin.data
      : undefined;
  // Captured BEFORE `obj.origin` is (re-)resolved: `createdByFromOrigin`'s
  // own contract (its doc comment, server/lib/agentOrigin.ts) is "fall back
  // to this ONLY when the origin itself is genuinely unresolvable" — for
  // every KNOWN runtime it ignores this argument outright. Threading the
  // payload's OWN `createdBy` through as that fallback (bonus constat,
  // revue adversariale) — rather than discarding it — preserves the
  // deliberately-supported case (chip 2026-07-28) where an operator declares
  // Codex as the author on a payload with NO env markers at all (origin
  // resolves to "unknown"), while still closing the contradiction the constat
  // actually describes: a copied template's stale author field can no longer
  // survive independently once a REAL origin resolves, since this now always
  // reassigns (never `??=`-skips) through the SAME two-argument call
  // `saveConversation` itself makes downstream.
  const payloadCreatedBy = obj.createdBy as 'claude' | 'user' | 'codex' | undefined;
  obj.origin = resolveAgentOrigin({
    env: process.env,
    cwd: process.cwd(),
    source: 'cli',
    explicit: originOverride ?? trustedPayloadOrigin,
    git: readGitBranch,
  });
  obj.createdBy = createdByFromOrigin(obj.origin as AgentOrigin, payloadCreatedBy);

  // IDENTITY GUARD (security-critical): the CLI is the agent (actor='claude')
  // write path. The loop may author questions/approvals (items WITHOUT a
  // response) but must NEVER author an answer/decision. Reject a forged
  // response.decision BEFORE schema validation so a malformed-but-answered body
  // is caught too. Only the human (dashboard PUT, actor='user') may answer.
  const guard = checkConversationWrite(obj, 'claude');
  if (!guard.allowed) {
    fail(guard.reason);
  }

  const parsed = ConversationSchema.safeParse(obj);
  if (!parsed.success) {
    fail(
      `conversation fails schema —\n${describeConversationSchemaError(obj, parsed.error)}\n` +
        SCHEMA_SOURCE_HINT,
    );
  }
  // We validated to surface a clean error, but we pass the RAW object (with
  // defaults filled) to saveConversation — exactly like the HTTP route passes
  // req.body. saveConversation re-validates and recomputes status itself;
  // handing it a zod-parsed value would be a needless double-parse.
  const id = parsed.data.id;
  if (parsed.data.project.slug !== slug) {
    fail(`project.slug "${parsed.data.project.slug}" does not match path slug "${slug}"`);
  }

  const existing = await getConversation(slug, id);
  if (existing && !force) {
    fail(
      `conversation "${id}" already exists (it may hold user answers). Re-run with --force to overwrite.`,
    );
  }
  // When overwriting, satisfy the store's optimistic lock by echoing the
  // current updatedAt; otherwise saveConversation would 409.
  if (existing) obj.updatedAt = existing.updatedAt;

  const result = await saveConversation(slug, id, obj, { allowSecretLike });
  if (!result.ok) {
    if ('secretBlocked' in result) {
      fail(
        `store refused the write — high-confidence secret shape(s) detected ` +
          `(${result.patterns.join(', ')}). A secret VALUE must never live in a ` +
          `conversation; deliver it via a secret_request item (le Coffre). If a ` +
          `hint merely ILLUSTRATES a key shape, re-run with --allow-secret-like.`,
      );
    }
    fail(`store rejected the write — ${saveFailureReason(result)}`);
  }
  const written = result.conversation;
  const counted = written.items.filter(countsTowardCompletion).length;
  process.stdout.write(
    `VERDICT: CREATED\n` +
      // ABSOLUTE path (lot 3's external hook derives dataRoot() from it) —
      // was `data/conversations/<slug>/<id>.json`, relative to WHATEVER cwd
      // the CLI happened to run from.
      `Path: ${path.join(dataDir(), slug, `${written.id}.json`)}\n` +
      `Conversation: ${written.id} — ${written.title}\n` +
      `Status: ${written.status}\n` +
      `Items: ${written.items.length} (${counted} actionable)\n` +
      `Origin: ${written.origin?.runtime ?? 'unknown'} ${written.origin?.sessionId ?? '-'} (${written.origin?.capturedBy ?? 'none'})\n` +
      `Next: tell the user to open the conversation in the workstation app and answer.\n`,
  );
}

/**
 * Append-only counterpart to `cmdCreate` — see the header doc comment for the
 * rationale. Reads the existing conversation, validates ONLY the new item(s)
 * (schema + identity guard), and writes back the existing items UNTOUCHED
 * plus the new tail, through the same `saveConversation` choke point (optimistic
 * lock + computeStatus + atomic write) every other write path uses.
 */
async function cmdAddItem(slug: string, id: string, source: string) {
  if (!isSafeSegment(slug) || !isSafeSegment(id)) fail('unsafe slug or id');
  const raw = source === '-' ? await readStdin() : await fs.readFile(source, 'utf8');

  let json: unknown;
  try {
    json = JSON.parse(raw);
  } catch (err) {
    fail(`payload is not valid JSON — ${(err as Error).message}`);
  }

  const existing = await getConversation(slug, id);
  if (!existing) {
    fail(
      `conversation "${id}" not found under "${slug}" — add-item only appends ` +
        `to an EXISTING conversation; use "convo create" to author a new one.`,
    );
  }

  // Accept either a single item object or an array of items.
  const rawItems: unknown[] = Array.isArray(json) ? json : [json];
  if (rawItems.length === 0) fail('no item(s) provided');

  // IDENTITY GUARD (security-critical), scoped to ONLY the new item(s) being
  // appended — NEVER re-run against `existing.items`, which may already carry
  // human responses. Re-checking the whole merged body (like `create` does)
  // would always reject an append to an answered conversation, defeating the
  // entire point of this command. Checked BEFORE schema validation, exactly
  // like `cmdCreate`, so a forged response is caught even in a malformed body.
  const guard = checkConversationWrite({ items: rawItems }, 'claude');
  if (!guard.allowed) {
    fail(guard.reason);
  }

  const newItems: Item[] = [];
  for (const it of rawItems) {
    const parsed = ItemSchema.safeParse(it);
    if (!parsed.success) {
      fail(`item fails schema —\n${describeItemSchemaError(it, parsed.error)}\n${SCHEMA_SOURCE_HINT}`);
    }
    newItems.push(parsed.data);
  }

  const existingIds = new Set(existing.items.map((it) => it.id));
  for (const it of newItems) {
    if (existingIds.has(it.id)) {
      fail(`item id "${it.id}" already exists in conversation "${id}"`);
    }
  }

  // APPEND ONLY: `existing.items` is carried through exactly as read from
  // disk — never re-authored, re-ordered, or mutated — only the new tail is
  // added. `updatedAt` is echoed from disk (same convention `cmdCreate`
  // --force uses) so the store's optimistic lock accepts the write.
  const merged: Record<string, unknown> = {
    ...existing,
    items: [...existing.items, ...newItems],
  };

  const result = await saveConversation(slug, id, merged);
  if (!result.ok) {
    if ('secretBlocked' in result) {
      fail(
        `store refused the write — high-confidence secret shape(s) detected ` +
          `(${result.patterns.join(', ')}). A secret VALUE must never live in a ` +
          `conversation; deliver it via a secret_request item (le Coffre).`,
      );
    }
    fail(`store rejected the write — ${saveFailureReason(result)}`);
  }
  const written = result.conversation;
  process.stdout.write(
    `VERDICT: ADDED\n` +
      `Path: data/conversations/${slug}/${written.id}.json\n` +
      `Conversation: ${written.id} — ${written.title}\n` +
      `Added item(s): ${newItems.map((it) => it.id).join(', ')}\n` +
      `Status: ${written.status}\n` +
      `Items: ${written.items.length}\n`,
  );
}

async function cmdRead(slug: string, id: string) {
  if (!isSafeSegment(slug) || !isSafeSegment(id)) fail('unsafe slug or id');
  const conv = await getConversation(slug, id);
  if (!conv) fail(`conversation "${id}" not found under "${slug}"`);
  const lines: string[] = [
    `VERDICT: READ`,
    `Conversation: ${conv.id} — ${conv.title}`,
    `Status: ${conv.status}   (project: ${slug})`,
    `Items: ${conv.items.length}`,
    ``,
  ];
  for (const it of conv.items) {
    lines.push(`- [${it.status}] ${it.id} (${it.kind}): ${it.title ?? it.prompt}`);
    lines.push(`    response: ${renderResponse(it)}`);
    if (it.comment) lines.push(`    comment: ${it.comment}`);
  }
  process.stdout.write(lines.join('\n') + '\n');
}

async function cmdList(slug: string) {
  if (!isSafeSegment(slug)) fail(`unsafe project slug "${slug}"`);
  const convs = await listConversations(slug);
  if (!convs.length) {
    process.stdout.write(`VERDICT: READ\n(no conversations under "${slug}")\n`);
    return;
  }
  const lines = [`VERDICT: READ`, `Project: ${slug} — ${convs.length} conversation(s)`, ``];
  for (const c of convs) {
    lines.push(`- [${c.status}] ${c.id} — ${c.title} (${c.answeredCount}/${c.itemCount})`);
  }
  process.stdout.write(lines.join('\n') + '\n');
}

async function cmdFollowups(slug?: string) {
  if (slug && !isSafeSegment(slug)) fail(`unsafe project slug "${slug}"`);
  const pending = await findPendingFollowups(slug);
  if (!pending.length) {
    process.stdout.write('VERDICT: READ\n(no pending followups)\n');
    return;
  }
  const lines = [
    `VERDICT: READ`,
    `Followups pending: ${pending.length}${slug ? ` (project: ${slug})` : ''}`,
    ``,
  ];
  for (const m of pending) {
    lines.push(
      `- [${m.status}] ${m.project.slug}/${m.id} — ${m.title} (${m.answeredCount}/${m.itemCount} répondus)`,
    );
  }
  process.stdout.write(lines.join('\n') + '\n');
}

async function cmdHandled(slug: string, id: string) {
  if (!isSafeSegment(slug) || !isSafeSegment(id)) fail('unsafe slug or id');
  const conv = await getConversation(slug, id);
  if (!conv) fail(`conversation "${id}" not found under "${slug}"`);
  // Echo the on-disk updatedAt so the store's optimistic lock accepts the PUT.
  const result = await saveConversation(slug, id, {
    ...conv,
    agentFollowupStatus: 'handled',
  });
  if (!result.ok) {
    fail(`store rejected the write — ${saveFailureReason(result)}`);
  }
  process.stdout.write(
    `VERDICT: HANDLED\n` +
      `Conversation: ${result.conversation.id} — ${result.conversation.title}\n` +
      `agentFollowupStatus: ${result.conversation.agentFollowupStatus}\n`,
  );
}

