359	  // only trusted when its `runtime` is an AGENT runtime ('claude'/'codex').
360	  // `templates/conversations/*.json` — exactly what CLAUDE.md points agents
361	  // at — historically carried `origin.runtime:'user'`/`'claude-ai'` from
362	  // whoever last saved that template from the dashboard/claude.ai; letting
363	  // that survive into `explicit` here would have `resolveAgentOrigin`
364	  // stamp the copying AGENT's own conversation as authored by a human/
365	  // remote session it never was, at a rank the hook/backfill repair paths
366	  // can never take back. A non-agent runtime coming from the FILE is
367	  // dropped (falls through to env detection below) — `--origin-json` (this
368	  // command's own flag, a deliberate operator signal, never a copied file)
369	  // is NOT filtered: `originOverride` still wins outright via `??`.
370	  const payloadOrigin = AgentOriginSchema.partial().safeParse(obj.origin);
371	  const AGENT_RUNTIMES_ONLY = new Set(['claude', 'codex']);
372	  const trustedPayloadOrigin =
373	    payloadOrigin.success && (!payloadOrigin.data.runtime || AGENT_RUNTIMES_ONLY.has(payloadOrigin.data.runtime))
374	      ? payloadOrigin.data
375	      : undefined;
376	  // Captured BEFORE `obj.origin` is (re-)resolved: `createdByFromOrigin`'s
377	  // own contract (its doc comment, server/lib/agentOrigin.ts) is "fall back
378	  // to this ONLY when the origin itself is genuinely unresolvable" — for
379	  // every KNOWN runtime it ignores this argument outright. Threading the
380	  // payload's OWN `createdBy` through as that fallback (bonus constat,
381	  // revue adversariale) — rather than discarding it — preserves the
382	  // deliberately-supported case (chip 2026-07-28) where an operator declares
383	  // Codex as the author on a payload with NO env markers at all (origin
384	  // resolves to "unknown"), while still closing the contradiction the constat
385	  // actually describes: a copied template's stale author field can no longer
386	  // survive independently once a REAL origin resolves, since this now always
387	  // reassigns (never `??=`-skips) through the SAME two-argument call
