396	  });
397	  obj.createdBy = createdByFromOrigin(obj.origin as AgentOrigin, payloadCreatedBy);
398	
399	  // IDENTITY GUARD (security-critical): the CLI is the agent (actor='claude')
400	  // write path. The loop may author questions/approvals (items WITHOUT a
401	  // response) but must NEVER author an answer/decision. Reject a forged
402	  // response.decision BEFORE schema validation so a malformed-but-answered body
403	  // is caught too. Only the human (dashboard PUT, actor='user') may answer.
404	  const guard = checkConversationWrite(obj, 'claude');
405	  if (!guard.allowed) {
406	    fail(guard.reason);
407	  }
408	
409	  const parsed = ConversationSchema.safeParse(obj);
410	  if (!parsed.success) {
411	    fail(
412	      `conversation fails schema —\n${describeConversationSchemaError(obj, parsed.error)}\n` +
413	        SCHEMA_SOURCE_HINT,
414	    );
415	  }
416	  // We validated to surface a clean error, but we pass the RAW object (with
417	  // defaults filled) to saveConversation — exactly like the HTTP route passes
418	  // req.body. saveConversation re-validates and recomputes status itself;
419	  // handing it a zod-parsed value would be a needless double-parse.
420	  const id = parsed.data.id;
421	  if (parsed.data.project.slug !== slug) {
422	    fail(`project.slug "${parsed.data.project.slug}" does not match path slug "${slug}"`);
423	  }
424	
425	  const existing = await getConversation(slug, id);
426	  if (existing && !force) {
427	    fail(
428	      `conversation "${id}" already exists (it may hold user answers). Re-run with --force to overwrite.`,
429	    );
430	  }
431	  // When overwriting, satisfy the store's optimistic lock by echoing the
432	  // current updatedAt; otherwise saveConversation would 409.
433	  if (existing) obj.updatedAt = existing.updatedAt;
434	
435	  const result = await saveConversation(slug, id, obj, { allowSecretLike });
436	  if (!result.ok) {
437	    if ('secretBlocked' in result) {
438	      fail(
439	        `store refused the write — high-confidence secret shape(s) detected ` +
440	          `(${result.patterns.join(', ')}). A secret VALUE must never live in a ` +
441	          `conversation; deliver it via a secret_request item (le Coffre). If a ` +
442	          `hint merely ILLUSTRATES a key shape, re-run with --allow-secret-like.`,
443	      );
444	    }
445	    fail(`store rejected the write — ${saveFailureReason(result)}`);
446	  }
447	  const written = result.conversation;
448	  const counted = written.items.filter(countsTowardCompletion).length;
449	  process.stdout.write(
450	    `VERDICT: CREATED\n` +
451	      // ABSOLUTE path (lot 3's external hook derives dataRoot() from it) —
452	      // was `data/conversations/<slug>/<id>.json`, relative to WHATEVER cwd
453	      // the CLI happened to run from.
454	      `Path: ${path.join(dataDir(), slug, `${written.id}.json`)}\n` +
455	      `Conversation: ${written.id} — ${written.title}\n` +
456	      `Status: ${written.status}\n` +
457	      `Items: ${written.items.length} (${counted} actionable)\n` +
458	      `Origin: ${written.origin?.runtime ?? 'unknown'} ${written.origin?.sessionId ?? '-'} (${written.origin?.capturedBy ?? 'none'})\n` +
459	      `Next: tell the user to open the conversation in the workstation app and answer.\n`,
460	  );
461	}
