/**
 * Scanne UN projet. `slug` est déjà résolu par l'appelant (`scanProjects()`),
 * collision-aware sur la liste COMPLÈTE des noms de dossiers du lot en cours
 * — voir `disambiguateSlugCollisions()` (`server/services/slug.ts`, LOT 2
 * chip 2026-07-28). `scanOne()` ne recalcule PLUS `slugify(name)` en local :
 * avant ce chip, deux dossiers en collision de slug (ex. `Home-Spectors` et
 * `home_spectors`) produisaient ici le MÊME `project.slug` nu, divergent du
 * slug désambiguïsé que `gitScanner.listGitRepos()` calcule pour les mêmes
 * dossiers — ce même slug nu étant celui gravé dans `project.slug` de chaque
 * conversation/chip créé pour ce projet.
 */
async function scanOne(name: string, slug: string): Promise<ProjectSummary> {
  const dir = path.join(projectsRoot(), name);

  // Every helper below already swallows its own errors, so a single bad
  // project yields a degraded-but-valid summary instead of taking the whole
  // scan down. statMtimeSafe is the last unguarded fs call and is wrapped too.
  const [
    pkg,
    isGit,
    packageManager,
    hasClaudeMd,
    hasReadme,
    lastModified,
    lastCommitDate,
    conversationCount,
  ] = await Promise.all([
    readJsonSafe(path.join(dir, 'package.json')),
    pathExists(path.join(dir, '.git')),
    detectPackageManager(dir),
    pathExists(path.join(dir, 'CLAUDE.md')),
    (async () =>
      (await pathExists(path.join(dir, 'README.md'))) ||
      (await pathExists(path.join(dir, 'readme.md'))))(),
    statMtimeSafe(dir),
    getLastCommitDate(dir),
    countConversations(slug),
  ]);

  const { type, framework } = classify(pkg);

  return {
    slug,
    name,
    path: dir,
    isGit,
    type,
    framework,
    packageManager,
    lastCommitDate,
    lastModified,
    hasClaudeMd,
    hasReadme,
    conversationCount,
  };
}

/* -------------------------------------------------------------------------- */
/*  Public API                                                                */
/* -------------------------------------------------------------------------- */

export async function scanProjects(refresh = false): Promise<ProjectSummary[]> {
  if (refresh) {
    cache = null;
  }
  if (!refresh && cache && Date.now() - cache.at < SCAN_CACHE_TTL_MS) {
    return cache.projects;
  }

  let dirents: import('node:fs').Dirent[];
  try {
    dirents = await fs.readdir(projectsRoot(), { withFileTypes: true });
  } catch {
    // Projects root missing/unreadable -> empty list, do not crash.
    cache = { at: Date.now(), projects: [] };
    return [];
  }

  const names = dirents
    .filter((d) => d.isDirectory())
    .map((d) => d.name)
    .filter((name) => !name.startsWith('.'));

  // Résolution de slug collision-aware sur le LOT ENTIER avant tout scan
  // individuel (même stratégie que `gitScanner.listGitRepos()`, fonction
  // PARTAGÉE — voir la docstring de `disambiguateSlugCollisions()`) : deux
  // noms distincts qui `slugify()`ent vers la même valeur reçoivent chacun un
  // slug distinct et stable, jamais dépendant de l'ordre de `readdir()`.
  const slugCandidates = names.map((name) => ({ name, slug: slugify(name) }));
  disambiguateSlugCollisions(slugCandidates);
  const slugByName = new Map(slugCandidates.map((c) => [c.name, c.slug]));

  const CONCURRENCY_LIMIT = 10;
  const settled = await mapConcurrent(names, CONCURRENCY_LIMIT, (name) =>
    scanOne(name, slugByName.get(name) ?? slugify(name)),
  );
  const projects = settled
    .filter(
      (r): r is PromiseFulfilledResult<ProjectSummary> => r.status === 'fulfilled',
    )
    .map((r) => r.value);

  projects.sort((a, b) => a.name.localeCompare(b.name));

  cache = { at: Date.now(), projects };
  return projects;
}

/** Explicitly clear the in-memory scan cache to enforce read-after-write consistency. */
export function clearProjectScanCache(): void {
  cache = null;
}

export async function getProject(slug: string): Promise<ProjectSummary | null> {
  const projects = await scanProjects();
  return projects.find((p) => p.slug === slug) ?? null;
}

