import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import os from 'node:os';
import path from 'node:path';
import { mkdtemp, mkdir, rm } from 'node:fs/promises';

/**
 * `convo create` with `createdBy: 'codex'` — LOT 12, chip
 * 2026-07-28-convo-cli-reconnaitre-codex-comme-auteur. Reproduces the exact
 * repro from the chip: `bun run convo create <slug> -` piping a payload with
 * `createdBy: "codex"` used to fail schema validation ("Invalid option:
 * expected one of claude|user"). It must now succeed, exactly like a
 * `createdBy: "claude"` payload does.
 *
 * Exercised as a real SUBPROCESS (same convention as convo.watch.test.ts):
 * `create`'s whole point (stdin payload -> file on disk) only exists at the
 * process boundary.
 */

const CLI = path.join(import.meta.dir, 'convo.ts');
const ISO = '2026-07-28T00:00:00.000Z';
const SLUG = 'demo-codex-author';

let root = '';

function payload(id: string, createdBy: string) {
  return JSON.stringify({
    schemaVersion: 1,
    id,
    project: { slug: SLUG, name: 'Demo Codex Author' },
    title: 'Codex-authored conversation',
    status: 'pending',
    items: [
      {
        id: 'q1',
        kind: 'question',
        prompt: 'Une question posée par Codex ?',
        status: 'pending',
      },
    ],
    createdAt: ISO,
    updatedAt: ISO,
    createdBy,
  });
}

// D2/D3 (chantier « provenance de session », lot 2): `convo create` now
// resolves a real `AgentOrigin` from `process.env` (server/lib/agentOrigin.ts)
// and `saveConversation` (lot 1) DERIVES `createdBy` from that origin,
// overriding whatever the payload itself claims once a stronger signal
// exists — so this file's whole point (proving the schema accepts a
// self-declared `createdBy: "codex"`) only stays meaningful when the CLI
// subprocess runs with NO Claude/Codex session env markers (origin resolves
// to `runtime: 'unknown'`, at which point `createdByFromOrigin` falls back
// to the payload's own `createdBy` — exactly the historical behavior this
// test asserts). Without this, running the suite FROM an actual Claude Code
// session (which really does set `CLAUDE_CODE_SESSION_ID`) would silently
// re-derive `createdBy: 'claude'` regardless of the payload.
const ORIGIN_ENV_KEYS = [
  'CLAUDE_CODE_SESSION_ID',
  'CLAUDE_CODE_HOST_SESSION_ID',
  'CLAUDE_CODE_ENTRYPOINT',
  'CLAUDE_CODE_CHILD_SESSION',
  'CODEX_THREAD_ID',
  'CODEX_SESSION_ID',
  'MCP_CALLER_RUNTIME',
] as const;

function spawnCreate(id: string, createdBy: string) {
  const env: Record<string, string | undefined> = { ...process.env, WORKSTATION_ROOT: root };
  for (const k of ORIGIN_ENV_KEYS) delete env[k];
  const proc = Bun.spawn(['bun', CLI, 'create', SLUG, '-'], {
    env,
    stdin: 'pipe',
    stdout: 'pipe',
    stderr: 'pipe',
  });
  proc.stdin.write(payload(id, createdBy));
  proc.stdin.end();
  return proc;
}

beforeAll(async () => {
  root = await mkdtemp(path.join(os.tmpdir(), 'wsconvo-create-codex-'));
  await mkdir(path.join(root, 'data', 'conversations', SLUG), { recursive: true });
});

afterAll(async () => {
  await rm(root, { recursive: true, force: true });
});

describe('convo create — createdBy: codex', () => {
  test('a payload with createdBy: "codex" is accepted (schema validates, file is written)', async () => {
    const proc = spawnCreate('2026-07-28-codex-create-test', 'codex');
    const [exitCode, stdout, stderr] = await Promise.all([
      proc.exited,
      new Response(proc.stdout).text(),
      new Response(proc.stderr).text(),
    ]);
    expect(stderr).toBe('');
    expect(exitCode).toBe(0);
    expect(stdout).toContain('VERDICT: CREATED');

    const written = await Bun.file(
      path.join(root, 'data', 'conversations', SLUG, '2026-07-28-codex-create-test.json'),
    ).json();
    expect(written.createdBy).toBe('codex');
  });

  test('a payload with createdBy: "claude" still works (unaffected by the widened enum)', async () => {
    const proc = spawnCreate('2026-07-28-claude-create-test', 'claude');
    const exitCode = await proc.exited;
    expect(exitCode).toBe(0);
  });
});
