import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import os from 'node:os';
import path from 'node:path';
import { mkdtemp, mkdir, realpath, rm, writeFile } from 'node:fs/promises';

import { ConversationSchema } from '../../src/types/conversation';
import {
  applyConversationDraftDefaults,
  resolveDraftProject,
  type DraftProject,
} from './conversationDraft';
import { clearProjectScanCache } from './projectScanner';

/**
 * Chip 2026-09-25-fill-convo-project-from-the-create-slug — the defaults
 * `convo create` / MCP `convo_create` / `capture_gate` apply BEFORE schema
 * validation. The schema itself is never loosened: every "accepted" case
 * below is checked against the real `ConversationSchema`.
 */

const NOW = '2026-09-25T12:00:00.000Z';
const SLUG = 'temps-chantier-code-app';

function minimalDraft(): Record<string, unknown> {
  return {
    id: '2026-09-25-minimal',
    title: 'Brouillon minimal',
    summary: 'Seulement id, title, summary et des items id/kind/title/body.',
    items: [{ id: 'n1', kind: 'note', title: 'Une note', body: 'Le corps de la note.' }],
  };
}

function stubResolver(project: DraftProject) {
  const calls: string[] = [];
  const resolve = async (slug: string) => {
    calls.push(slug);
    return project;
  };
  return { calls, resolve };
}

describe('applyConversationDraftDefaults', () => {
  test('project absent → rempli depuis le slug, + tous les défauts ; passe le schéma', async () => {
    const draft = minimalDraft();
    const { calls, resolve } = stubResolver({ slug: SLUG, name: 'Temps Chantier', path: '/p/tc' });

    const error = await applyConversationDraftDefaults(draft, SLUG, { now: NOW, resolveProject: resolve });

    expect(error).toBeNull();
    expect(calls).toEqual([SLUG]);
    expect(draft.project).toEqual({ slug: SLUG, name: 'Temps Chantier', path: '/p/tc' });
    expect(draft.schemaVersion).toBe(1);
    expect(draft.status).toBe('pending');
    expect(draft.createdAt).toBe(NOW);
    expect(draft.updatedAt).toBe(NOW);
    const [item] = draft.items as Record<string, unknown>[];
    expect(item.status).toBe('pending');
    expect(item.prompt).toBe('Une note');
    expect(ConversationSchema.safeParse(draft).success).toBe(true);
  });

  test('project.slug différent du slug du chemin → refus explicite, brouillon intact', async () => {
    const draft = { ...minimalDraft(), project: { slug: 'autre-projet', name: 'Autre' } };
    const before = structuredClone(draft);
    const { calls, resolve } = stubResolver({ slug: SLUG, name: 'x' });

    const error = await applyConversationDraftDefaults(draft, SLUG, { now: NOW, resolveProject: resolve });

    expect(error).toContain('project.slug « autre-projet » ≠ slug du chemin « temps-chantier-code-app »');
    expect(error).toContain('retire "project"');
    expect(draft).toEqual(before);
    expect(calls).toEqual([]);
  });

  test('project complet et cohérent → gardé tel quel, sans résolution', async () => {
    const project = { slug: SLUG, name: 'Nom choisi par l’agent' };
    const draft = { ...minimalDraft(), project };
    const { calls, resolve } = stubResolver({ slug: SLUG, name: 'ignoré' });

    expect(await applyConversationDraftDefaults(draft, SLUG, { now: NOW, resolveProject: resolve })).toBeNull();
    expect(draft.project).toEqual(project);
    expect(calls).toEqual([]);
  });

  test('project partiel → champs manquants complétés, champs fournis gardés', async () => {
    const { resolve } = stubResolver({ slug: SLUG, name: 'Temps Chantier', path: '/p/tc' });

    const onlyName = { ...minimalDraft(), project: { name: 'Mon nom' } };
    expect(await applyConversationDraftDefaults(onlyName, SLUG, { now: NOW, resolveProject: resolve })).toBeNull();
    expect(onlyName.project).toEqual({ slug: SLUG, name: 'Mon nom', path: '/p/tc' });

    const onlySlug = { ...minimalDraft(), project: { slug: SLUG } };
    expect(await applyConversationDraftDefaults(onlySlug, SLUG, { now: NOW, resolveProject: resolve })).toBeNull();
    expect(onlySlug.project).toEqual({ slug: SLUG, name: 'Temps Chantier', path: '/p/tc' });
  });

  test('valeurs déjà présentes jamais écrasées (statuts, dates, prompt, schemaVersion)', async () => {
    const draft: Record<string, unknown> = {
      ...minimalDraft(),
      schemaVersion: 2,
      status: 'in_progress',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-02T00:00:00.000Z',
      items: [{ id: 'q1', kind: 'question', title: 'Court', prompt: 'La vraie question ?', status: 'skipped' }],
    };
    const { resolve } = stubResolver({ slug: SLUG, name: 'x' });

    expect(await applyConversationDraftDefaults(draft, SLUG, { now: NOW, resolveProject: resolve })).toBeNull();
    expect(draft.schemaVersion).toBe(2); // le schéma le refusera ensuite : rien n'est relâché
    expect(draft.status).toBe('in_progress');
    expect(draft.createdAt).toBe('2026-01-01T00:00:00.000Z');
    expect(draft.updatedAt).toBe('2026-01-02T00:00:00.000Z');
    const [item] = draft.items as Record<string, unknown>[];
    expect(item.prompt).toBe('La vraie question ?');
    expect(item.status).toBe('skipped');
  });

  test('item sans prompt ni title → rien d’inventé, le schéma refuse toujours', async () => {
    const draft = { ...minimalDraft(), items: [{ id: 'n1', kind: 'note', body: 'corps' }] };
    const { resolve } = stubResolver({ slug: SLUG, name: 'x' });

    expect(await applyConversationDraftDefaults(draft, SLUG, { now: NOW, resolveProject: resolve })).toBeNull();
    expect((draft.items[0] as Record<string, unknown>).prompt).toBeUndefined();
    expect(ConversationSchema.safeParse(draft).success).toBe(false);
  });

  test('corps non-objet → refus clair', async () => {
    for (const bad of [null, [], 'texte', 42]) {
      const error = await applyConversationDraftDefaults(bad, SLUG, { now: NOW });
      expect(error).toContain('doit être un objet JSON');
    }
  });
});

describe('resolveDraftProject', () => {
  let tmp = '';
  const saved = {
    root: process.env.WORKSTATION_ROOT,
    dataRoot: process.env.WORKSTATION_DATA_ROOT,
    projects: process.env.PROJECTS_ROOT,
  };

  beforeAll(async () => {
    tmp = await realpath(await mkdtemp(path.join(os.tmpdir(), 'ws-convo-draft-')));
    process.env.WORKSTATION_ROOT = tmp;
    delete process.env.WORKSTATION_DATA_ROOT;
    process.env.PROJECTS_ROOT = path.join(tmp, 'projects');
    await mkdir(path.join(tmp, 'projects', 'MonProjet'), { recursive: true });
    await mkdir(path.join(tmp, 'projects', 'deja-connu'), { recursive: true });
    const convDir = path.join(tmp, 'data', 'conversations', 'deja-connu');
    await mkdir(convDir, { recursive: true });
    await writeFile(
      path.join(convDir, '2026-09-01-ancienne.json'),
      JSON.stringify({
        schemaVersion: 1,
        id: '2026-09-01-ancienne',
        project: { slug: 'deja-connu', name: 'Déjà Connu' },
        title: 'Ancienne',
        status: 'pending',
        items: [{ id: 'q1', kind: 'question', prompt: 'Q ?', status: 'pending' }],
        createdAt: NOW,
        updatedAt: NOW,
      }),
    );
    clearProjectScanCache();
  });

  afterAll(async () => {
    for (const [key, value] of [
      ['WORKSTATION_ROOT', saved.root],
      ['WORKSTATION_DATA_ROOT', saved.dataRoot],
      ['PROJECTS_ROOT', saved.projects],
    ] as const) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    clearProjectScanCache();
    await rm(tmp, { recursive: true, force: true });
  });

  test('nom déjà affiché par le hub pour ce slug (conversation existante) en priorité', async () => {
    expect(await resolveDraftProject('deja-connu')).toEqual({
      slug: 'deja-connu',
      name: 'Déjà Connu',
      path: path.join(tmp, 'projects', 'deja-connu'),
    });
  });

  test('sinon le registre des projets (nom du dossier + chemin)', async () => {
    expect(await resolveDraftProject('monprojet')).toEqual({
      slug: 'monprojet',
      name: 'MonProjet',
      path: path.join(tmp, 'projects', 'MonProjet'),
    });
  });

  test('sinon le slug lui-même', async () => {
    expect(await resolveDraftProject('inconnu')).toEqual({ slug: 'inconnu', name: 'inconnu' });
  });
});

