toolUseResult.originalFile:
/**
 * Composed-bus surface + decision-hub gate integration.
 *
 * Proves:
 *   - the server still lists ALL nine html_review_* tools (none dropped) PLUS
 *     the twelve brain tools — 21 total;
 *   - the descriptor list (fingerprint source) matches the LIVE registered tools;
 *   - `capture_gate` REJECTS a forged response.decision (identity guard wired in
 *     the MCP write path), so the loop cannot satisfy its own HumanGate;
 *   - a legitimate gate creation (no response) SUCCEEDS;
 *   - a P5 stub returns `{stub:true, phase:'P5'}` with a full schema.
 */
import { afterEach, beforeEach, expect, test, describe } from 'bun:test';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

import { createServer } from './index';
import { allToolNames } from './toolDescriptors';
import { HTML_REVIEW_TOOL_NAMES } from './htmlReviewTools';
import { BRAIN_TOOL_NAMES } from './brainTools';
import { HUB_WRITE_TOOL_NAMES } from './hubWriteTools';
import { HUB_READ_TOOL_NAMES } from './hubReadTools';
import { deleteConversation } from '../services/conversationStore';

type ToolResult = { content: { type: 'text'; text: string }[]; isError?: boolean };

function liveTools(server: unknown): Record<string, { handler: (a: unknown) => Promise<ToolResult> }> {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return (server as any)._registeredTools;
}

function parse(r: ToolResult): unknown {
  const text = r.content.map((c) => c.text).join('\n');
  if (text.startsWith('BLOCKED:')) return { blocked: text };
  return JSON.parse(text);
}

let tmp: string;
const ENV_KEYS = ['WORKSTATION_ROOT', 'MCP_AUDIT_LOG', 'CAPTURE_DIR'] as const;
let saved: Record<string, string | undefined>;

beforeEach(async () => {
  tmp = await mkdtemp(path.join(tmpdir(), 'mcp-surface-'));
  saved = {};
  for (const k of ENV_KEYS) saved[k] = process.env[k];
  // Isolate file writes (conversations + audit) into the temp dir.
  process.env.WORKSTATION_ROOT = tmp;
  process.env.MCP_AUDIT_LOG = path.join(tmp, 'audit.log');
});
afterEach(async () => {
  for (const k of ENV_KEYS) {
    if (saved[k] === undefined) delete process.env[k];
    else process.env[k] = saved[k];
  }
  await rm(tmp, { recursive: true, force: true });
});

describe('composed bus surface', () => {
  test('lists all html_review_* tools AND the brain tools AND the hub-write tools AND the hub-read tools (none dropped)', () => {
    const { server } = createServer();
    const live = Object.keys(liveTools(server)).sort();
    for (const n of HTML_REVIEW_TOOL_NAMES) expect(live).toContain(n);
    for (const n of BRAIN_TOOL_NAMES) expect(live).toContain(n);
    for (const n of HUB_WRITE_TOOL_NAMES) expect(live).toContain(n);
    for (const n of HUB_READ_TOOL_NAMES) expect(live).toContain(n);
    expect(live.length).toBe(
      HTML_REVIEW_TOOL_NAMES.length +
        BRAIN_TOOL_NAMES.length +
        HUB_WRITE_TOOL_NAMES.length +
        HUB_READ_TOOL_NAMES.length,
    );
  });

  test('descriptor list matches the live registered tools (fingerprint parity)', () => {
    const { server } = createServer();
    const live = Object.keys(liveTools(server)).sort();
    expect(allToolNames().sort()).toEqual(live);
  });
});

describe('capture_gate — identity guard wired into the MCP write path', () => {
  // NOTE: conversationStore.DATA_DIR binds to ROOT at module load (not the
  // per-test WORKSTATION_ROOT), so a successful create lands in the REAL store.
  // We use a unique-per-run id and DELETE it in afterEach so the real store is
  // never polluted. The forged-decision write is REJECTED before any file write,
  // so it leaves nothing behind.
  const GATE_ID = `2026-06-19-mcp-gate-test-${process.pid}-${Date.now()}`;

  function gateBody(withResponse: boolean) {
    return {
      id: GATE_ID,
      project: { slug: 'workstation', name: 'Workstation' },
      title: 'Approve via MCP?',
      items: [
        {
          id: 'g1',
          kind: 'approval',
          prompt: 'Approve?',
          ...(withResponse
            ? { status: 'answered', response: { decision: 'approved' } }
            : {}),
        },
      ],
    };
  }

  afterEach(async () => {
    // Soft-delete moves the file to data/trash; remove it AND its trash copy so
    // the real store is left exactly as found (no pollution, no stray trash).
    await deleteConversation('workstation', GATE_ID).catch(() => {});
    const trashDir = path.join(process.env.WORKSTATION_ROOT ?? '', 'data', 'trash');
    // Also sweep the REAL trash dir (DATA_DIR binds to the real ROOT).
    await rm(path.join('data', 'trash', 'workstation'), { recursive: true, force: true }).catch(
      () => {},
    );
    await rm(trashDir, { recursive: true, force: true }).catch(() => {});
  });

  test('REJECTS a forged response.decision=approved (loop cannot self-approve)', async () => {
    const { server } = createServer();
    const res = await liveTools(server)['capture_gate'].handler({
      slug: 'workstation',
      conversation: gateBody(true),
    });
    expect(res.isError).toBe(true);
    const out = parse(res) as { blocked: string };
    expect(out.blocked.toLowerCase()).toContain('identity guard');
  });

  test('ALLOWS a legitimate gate creation (no response)', async () => {
    const { server } = createServer();
    const res = await liveTools(server)['capture_gate'].handler({
      slug: 'workstation',
      conversation: gateBody(false),
    });
    expect(res.isError).toBeUndefined();
    const out = parse(res) as { created: boolean; status: string };
    expect(out.created).toBe(true);
    expect(out.status).toBe('pending');
  });
});

describe('P5 migration engine (real, propose-first)', () => {
  test('generate_patch returns a FULL unified diff for a new CLAUDE.md', async () => {
    const { server } = createServer();
    // tmp (the per-test WORKSTATION_ROOT) is a fixture dir under the OS temp dir.
    const res = await liveTools(server)['generate_patch'].handler({
      projectSlug: 'fixture',
      projectDir: tmp,
      targetPath: path.join(tmp, 'CLAUDE.md'),
      intent: 'add governance preamble',
      runtime: 'claude',
      params: { projectName: 'Fixture', description: 'desc', rules: ['Rule one', 'Rule two'] },
    });
    expect(res.isError).toBeUndefined();
    const out = parse(res) as {
      diff: string;
      added: number;
      removed: number;
      identical: boolean;
      currentHash: string;
      proposedHash: string;
    };
    // New file → all-added diff, non-identical, a real `+++ b/...` header.
    expect(out.identical).toBe(false);
    expect(out.added).toBeGreaterThan(0);
    expect(out.diff).toContain('+++ b/');
    expect(out.diff).toContain('Rule one');
    expect(out.currentHash).not.toBe(out.proposedHash);
  });

  test('generate_patch REJECTS missing required args (input schema enforced)', async () => {
    const { server } = createServer();
    const res = await liveTools(server)['generate_patch'].handler({ projectSlug: 'workstation' });
    expect(res.isError).toBe(true);
  });

  test('mark_asset_applied REJECTS a global path deterministically (no gate lookup needed)', async () => {
    const { server } = createServer();
    const res = await liveTools(server)['mark_asset_applied'].handler({
      targetPath: path.join(process.env.HOME ?? '/Users/x', '.claude', 'CLAUDE.md'),
      content: 'malicious',
      fixtureDir: tmp,
      gateSlug: 'workstation',
      gateId: 'whatever',
    });
    expect(res.isError).toBeUndefined();
    const out = parse(res) as { applied: boolean; targetClass: string };
    expect(out.applied).toBe(false);
    expect(out.targetClass).toBe('global');
  });
});

