 * array — ONE place so every list tool below signals truncation identically
 * instead of five copies silently drifting apart.
 */
function truncate<T>(items: T[], limit: number | undefined): { items: T[]; total: number; truncated: boolean } {
  const effective = limit ?? LIST_DEFAULT_LIMIT;
  const total = items.length;
  return { items: items.slice(0, effective), total, truncated: total > effective };
