  truncated: z.boolean(),
});

/* -------------------------------------------------------------------------- */
/*  convo_read                                                                */
/* -------------------------------------------------------------------------- */

const convoReadResultSchema = z.object({
  found: z.boolean(),
  conversation: ConversationSchema.optional(),
});

/**
 * REDACTED projection of `Conversation` for the REMOTE surface ONLY
 * (constat 4, revue adversariale, chantier « provenance de session ») — same
 * "redacted local schema, distinct from the shared source of truth" idiom
 * `gitStatusRepoSchema` below already uses for `git_status`. `convo_read`'s
 * description promises the FULL `AgentOrigin` (`cwd`, `repoRoot`, `branch`,
