content.content:
   * Constat 4 (revue adversariale, chantier « provenance de session »): when
   * true, `convo_read`'s `origin` (conversation-level AND per-item) is
   * projected onto `ReducedOriginSchema` — never the full `cwd`/`repoRoot`/
   * `branch`/`hostSessionId`/`entrypoint` a local caller gets. Set by the
   * REMOTE HTTP surface only (`server/mcp/remoteSurface.ts`) — the local
   * stdio bus keeps exposing the full origin, exactly as documented on the
   * tool itself and covered by `hubReadTools.test.ts`.
   */
  reduceOrigin?: boolean;
}

/**
 * Register `chips_list`, `chip_read`, `convo_list`, `convo_read`,
 * `remind_list`, `git_status` on `server` through the shared middleware.
 * Returns the registrar so the caller can read `registered` (the tool-list
 * fingerprint), exactly like `registerHubWriteTools`.
 */
export function registerHubReadTools(
  server: McpServer,
  opts?: RegisterHubReadToolsOptions,
): BrainToolRegistrar {
  const reg = opts?.registrar ?? new BrainToolRegistrar();
  const allow = opts?.allow;
  const wants = (name: string) => !allow || allow.has(name);

  /* ---- chips_list (READ) ---- */
  if (wants('chips_list')) {
    reg.register(server, {
      name: 'chips_list',
      description:
        'Liste les task chips (miroir de `bun run chips list`), optionnellement filtrés par slug de projet et/ou statuts. Chaque chip porte son `origin` réduit (runtime claude/codex/user, sessionId, couche de capture) quand résolu — PAS `cwd`/branche, uniquement via `chip_read`. Borné par `limit` (défaut 50, plafond 200) — tronqué avec `truncated`/`total` plutôt que silencieusement coupé.',
      access: 'read',
      annotations: READ_ONLY,
      inputSchema: {
        slug: z.string().optional().describe('Slug de projet sous PROJECTS_ROOT — tous les projets si absent'),
        status: z
          .array(z.enum(['open', 'launched', 'done', 'dismissed']))
          .optional()
          .describe('Filtre de statuts — tous les statuts si absent'),
        limit: limitSchema.describe(`Nombre max de chips (défaut ${LIST_DEFAULT_LIMIT}, plafond ${LIST_MAX_LIMIT})`),
      },
      outputSchema: chipsListResultSchema,
      handler: async (args) => {
        const all = await listChips({ slug: args.slug, status: args.status });
        const { items, total, truncated } = truncate(all, args.limit);
        return { chips: items as z.infer<typeof ChipMetaSchema>[], total, truncated };
      },
    });
  }

  /* ---- chip_read (READ) ---- */
  if (wants('chip_read')) {
    reg.register(server, {
      name: 'chip_read',
      description:
        'Lit un task chip par id (miroir de `getChip`/`findChip`, chipStore.ts) — objet complet, `origin` (runtime claude/codex/user, sessionId, cwd, branche…) inclus quand résolu. `slug` optionnel accélère la recherche ; sans lui, cherche dans tous les projets.',
      access: 'read',
      annotations: READ_ONLY,
      inputSchema: {
        id: z.string().min(1).describe('Id du chip'),
        slug: z.string().optional().describe('Slug de projet — si connu, évite un scan complet'),
      },
      outputSchema: chipReadResultSchema,
      handler: async (args) => {
        if (args.slug !== undefined && !isSafeSegment(args.slug)) {
          throw new Error(`slug invalide « ${args.slug} »`);
        }
        const chip = args.slug ? await getChip(args.slug, args.id) : await findChip(args.id);
        if (!chip) return { found: false };
        return { found: true, chip };
      },
    });
  }

  /* ---- convo_list (READ) ---- */
  if (wants('convo_list')) {
    reg.register(server, {
      name: 'convo_list',
      description:
        'Liste les conversations du hub de décisions pour un slug de projet (miroir de `listConversations`, conversationStore.ts). Chaque entrée porte son `origin` réduit (runtime claude/codex/user, sessionId, couche de capture) quand résolu — PAS `cwd`/branche, uniquement via `convo_read`. Borné par `limit` (défaut 50, plafond 200).',
      access: 'read',
      annotations: READ_ONLY,
      inputSchema: {
        slug: z.string().min(1).describe('Slug projet (dossier data/conversations/<slug>/)'),
        limit: limitSchema.describe(`Nombre max de conversations (défaut ${LIST_DEFAULT_LIMIT}, plafond ${LIST_MAX_LIMIT})`),
      },
      outputSchema: convoListResultSchema,
      handler: async (args) => {
        if (!isSafeSegment(args.slug)) {
          throw new Error(`slug invalide « ${args.slug} »`);
        }
        const all = await listConversations(args.slug);
        const { items, total, truncated } = truncate(all, args.limit);
        return { conversations: items, total, truncated };
      },
    });
  }

  /* ---- convo_read (READ) ---- */
  // Two SEPARATE `reg.register` calls (never one call with a ternary
  // `outputSchema`/return shape) so each branch's handler return type stays
  // narrowly tied to ITS OWN `outputSchema` — a single conditional call
  // would force TypeScript to unify both possible return shapes into one,
  // which the (deliberately different) reduced/full origin shapes can't
  // satisfy.
  if (wants('convo_read') && opts?.reduceOrigin) {
    reg.register(server, {
      name: 'convo_read',
      description:
        'Lit une conversation du hub de décisions EN ENTIER, items et réponses compris (miroir de `getConversation`, conversationStore.ts) — à la différence de `read_gate` qui ne renvoie qu’un résumé par item. `origin` est RÉDUIT (runtime, sessionId, couche de capture) — jamais cwd/repoRoot/branche, une session locale ne doit rien révéler de son environnement à un appelant distant.',
      access: 'read',
      annotations: READ_ONLY,
      inputSchema: {
        slug: z.string().min(1).describe('Slug projet'),
        id: z.string().min(1).describe('Id de la conversation'),
      },
      outputSchema: remoteConvoReadResultSchema,
      handler: async (args) => {
        if (!isSafeSegment(args.slug) || !isSafeSegment(args.id)) {
          throw new Error('slug ou id invalide');
        }
        const conversation = await getConversation(args.slug, args.id);
        if (!conversation) return { found: false };
        return { found: true, conversation: toRemoteConversation(conversation) };
      },
    });
  } else if (wants('convo_read')) {
    reg.register(server, {
      name: 'convo_read',
      description:
        'Lit une conversation du hub de décisions EN ENTIER, items et réponses compris (miroir de `getConversation`, conversationStore.ts), y compris son `origin` complet (runtime claude/codex/user/claude-ai, sessionId, cwd, branche…) — à la différence de `read_gate` qui ne renvoie qu’un résumé par item.',
      access: 'read',
      annotations: READ_ONLY,
      inputSchema: {
        slug: z.string().min(1).describe('Slug projet'),
        id: z.string().min(1).describe('Id de la conversation'),
      },
      outputSchema: convoReadResultSchema,
      handler: async (args) => {
        if (!isSafeSegment(args.slug) || !isSafeSegment(args.id)) {
          throw new Error('slug ou id invalide');
        }
        const conversation = await getConversation(args.slug, args.id);
        if (!conversation) return { found: false };
        return { found: true, conversation };
      },
    });
  }

  /* ---- remind_list (READ) ---- */
  if (wants('remind_list')) {
    reg.register(server, {
      name: 'remind_list',
      description:
        'Liste tous les items `reminder` (pending ET answered) de la conversation évergreen `_reminders` (miroir de `listAllReminders`, reminderStore.ts). Chaque item porte son `origin` COMPLET (runtime, sessionId, cwd, branche…) quand résolu — à la différence de `chips_list`/`convo_list`, un rappel n\'expose pas une version réduite. Borné par `limit` (défaut 50, plafond 200).',
      access: 'read',
      annotations: READ_ONLY,
      inputSchema: {
        limit: limitSchema.describe(`Nombre max de rappels (défaut ${LIST_DEFAULT_LIMIT}, plafond ${LIST_MAX_LIMIT})`),
      },
      outputSchema: remindListResultSchema,
      handler: async (args) => {
        const all = await listAllReminders();
        const { items, total, truncated } = truncate(all, args.limit);
        return { reminders: items, total, truncated };
      },
    });
  }

  /* ---- git_status (READ) ---- */
  if (wants('git_status')) {
    reg.register(server, {
      name: 'git_status',
      description:
        'État git résumé de tous les dépôts de la machine (miroir de `scanGit`, gitScanner.ts — lecture pure, AUCUNE mutation git). Sortie RÉDIGÉE : slug, branche, compteur dirty, `aheadTotal` — jamais d’identité (comptes/e-mails git).',
      access: 'read',
      annotations: READ_ONLY,
      inputSchema: {},
      outputSchema: gitStatusResultSchema,
      handler: async () => {
        const repos = await scanGit();
        return {
          repos: repos.map((r) => ({
            slug: r.slug,
            branch: r.currentBranch,
            dirtyFileCount: r.dirtyFileCount,
            aheadTotal: r.aheadTotal,
          })),
          total: repos.length,
        };
      },
    });
  }

  return reg;
}

