/**
 * Local-path redaction for the REMOTE MCP surface ONLY (claude.ai via OAuth,
 * `server/mcp/remoteSurface.ts`) — chip
 * 2026-09-25-redact-project-path-in-remote-convo-read.
 *
 * Same rule as the `origin` reduction `convo_read` already applied (constat 4,
 * chantier « provenance de session »): a remote caller has no business
 * learning this machine's filesystem layout. Every STRUCTURAL field that holds
 * a local absolute path is dropped (a `project.path`, a project state's
 * `doc.path`) or cut down to its basename (an attachment `href`, a string in a
 * loose record). Free text (prompts, bodies, answers, memory text) is content
 * the user wrote and is left untouched. The local stdio surface never calls
 * anything here.
 */
import path from 'node:path';

/** A string that IS a local absolute path (home, temp, volumes…) — whole
 *  string, not a path mentioned inside a sentence. */
const LOCAL_ABSOLUTE_PATH = /^(?:~|\/(?:Users|home|private|var|tmp|Volumes|opt|root))(?:\/\S*)?$/;

export function isLocalAbsolutePath(value: string): boolean {
  return LOCAL_ABSOLUTE_PATH.test(value);
}

/** `/Users/…/docs/roadmap.html` → `roadmap.html`; any other string unchanged. */
export function redactLocalPath(value: string): string {
  return isLocalAbsolutePath(value) ? path.basename(value) : value;
}

/** Deep copy of `value` where every string that is a local absolute path is
 *  cut down to its basename (`redactLocalPath`). For loose records whose
 *  shape is not known in advance (`meta`, a project state's `surfaces`…). */
export function scrubLocalPaths<T>(value: T): T {
  if (typeof value === 'string') return redactLocalPath(value) as T;
  if (Array.isArray(value)) return value.map((v) => scrubLocalPaths(v)) as T;
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([k, v]) => [k, scrubLocalPaths(v)]),
    ) as T;
  }
  return value;
}

/** `{ slug, name, path? }` → `{ slug, name }`. */
export function withoutProjectPath<P extends { slug: string; name: string }>(
  project: P,
): { slug: string; name: string } {
  return { slug: project.slug, name: project.name };
}

/** A project state mirrored from Convex (`project_state_get`): `doc.path`
 *  dropped, every other local path in its loose sections scrubbed. */
export function toRemoteProjectState(state: unknown): unknown {
  if (!state || typeof state !== 'object') return state;
  const { doc, ...rest } = state as Record<string, unknown>;
  if (!doc || typeof doc !== 'object') return scrubLocalPaths(rest);
  const { path: _localPath, ...docRest } = doc as Record<string, unknown>;
  return scrubLocalPaths({ ...rest, doc: docRest });
}

