/**
 * remoteSurface — Lot 3 (chantier MCP distant / connecteur claude.ai).
 *
 * Proves the remote HTTP surface is a HARD 12-tool whitelist, distinct from
 * (and strictly narrower than) the full 33-tool stdio bus:
 *   - REMOTE_TOOL_NAMES is a genuine subset of allToolNames() (no typo);
 *   - a real `tools/list` JSON-RPC round-trip (via the SDK's Client +
 *     InMemoryTransport — the same protocol machinery a real MCP client uses)
 *     against a server built by `createRemoteServer()` returns EXACTLY the 12
 *     whitelisted names, never more, never fewer;
 *   - none of the dangerous/local-only tools ever appear (P5 migration engine,
 *     capture_gate/ack_gate, any html_review_*);
 *   - `resources/list`/`prompts/list` are NOT SUPPORTED on the remote server
 *     (registerBrainResources/registerBrainPrompts are never called for it) —
 *     the SDK's low-level Server returns a JSON-RPC "Method not found" error
 *     for a method with no registered handler (see shared/protocol.js), which
 *     is what we assert here since that is what's actually OBSERVABLE over
 *     the wire (not an empty array — the capability itself doesn't exist);
 *   - calling `createRemoteServer()` repeatedly does NOT grow the SHARED
 *     registrar's `registered` fingerprint beyond the 12 unique tool names —
 *     the idempotency guarantee `middleware.ts` provides, exercised here
 *     through the real construction path (not a synthetic registrar).
 */
import { afterEach, beforeEach, expect, test, describe } from 'bun:test';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { InMemoryTransport } from '@modelcontextprotocol/sdk/inMemory.js';
import { McpError } from '@modelcontextprotocol/sdk/types.js';

import { createRemoteServer, REMOTE_TOOL_NAMES, remoteRegisteredToolNames } from './remoteSurface';
import { allToolNames } from './toolDescriptors';
import { getConversation } from '../services/conversationStore';
import { HUB_WRITE_TOOL_NAMES } from './hubWriteTools';

let tmp: string;
const ENV_KEYS = ['WORKSTATION_ROOT', 'MCP_AUDIT_LOG'] as const;
let saved: Record<string, string | undefined>;

beforeEach(async () => {
  tmp = await mkdtemp(path.join(tmpdir(), 'mcp-remote-surface-'));
  saved = {};
  for (const k of ENV_KEYS) saved[k] = process.env[k];
  process.env.WORKSTATION_ROOT = tmp;
  process.env.MCP_AUDIT_LOG = path.join(tmp, 'audit.log');
});
afterEach(async () => {
  for (const k of ENV_KEYS) {
    if (saved[k] === undefined) delete process.env[k];
    else process.env[k] = saved[k];
  }
  await rm(tmp, { recursive: true, force: true });
});

/** Connect a fresh SDK Client to a fresh remote McpServer via an in-memory pair. */
async function connectedClient(): Promise<Client> {
  const server = createRemoteServer();
  const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
  const client = new Client({ name: 'test-client', version: '0.0.0' });
  await Promise.all([client.connect(clientTransport), server.connect(serverTransport)]);
  return client;
}

describe('REMOTE_TOOL_NAMES', () => {
  test('is exactly the 12 documented names', () => {
    expect([...REMOTE_TOOL_NAMES].sort()).toEqual(
      [
        'chip_create',
        'chip_read',
        'chips_list',
        'convo_create',
        'convo_list',
        'convo_read',
        'git_status',
        'lessons_list_validated',
        'memory_search',
        'project_state_get',
        'remind_add',
        'remind_list',
      ].sort(),
    );
  });

  test('is a genuine subset of allToolNames() (no typo against the real bus surface)', () => {
    const all = new Set(allToolNames());
    for (const name of REMOTE_TOOL_NAMES) {
      expect(all.has(name)).toBe(true);
    }
  });
});

describe('tools/list over a real JSON-RPC round-trip', () => {
  test('returns EXACTLY the 12 whitelisted names — no more, no fewer', async () => {
    const client = await connectedClient();
    const { tools } = await client.listTools();
    const names = tools.map((t) => t.name).sort();
    expect(names).toEqual([...REMOTE_TOOL_NAMES].sort());
  });

  test('NEVER exposes the P5 migration engine / capture-gate tools or any html_review_* tool', async () => {
    const client = await connectedClient();
    const { tools } = await client.listTools();
    const names = new Set(tools.map((t) => t.name));
    for (const banned of [
      'generate_patch',
      'capture_gate',
      'ack_gate',
      'apply_patch_dry_run',
      'create_migration_campaign',
    ]) {
      expect(names.has(banned)).toBe(false);
    }
    for (const name of names) {
      expect(name.startsWith('html_review_')).toBe(false);
    }
  });
});

describe('resources/list and prompts/list — not supported on the remote surface', () => {
  test('resources/list rejects (no handler registered — registerBrainResources is never called remotely)', async () => {
    const client = await connectedClient();
    await expect(client.listResources()).rejects.toThrow();
    try {
      await client.listResources();
      throw new Error('expected rejection');
    } catch (e) {
      expect(e).toBeInstanceOf(McpError);
      expect((e as McpError).code).toBe(-32601); // MethodNotFound
    }
  });

  test('prompts/list rejects (no handler registered — registerBrainPrompts is never called remotely)', async () => {
    const client = await connectedClient();
    try {
      await client.listPrompts();
      throw new Error('expected rejection');
    } catch (e) {
      expect(e).toBeInstanceOf(McpError);
      expect((e as McpError).code).toBe(-32601); // MethodNotFound
    }
  });
});

