describe('convo_create through the remote surface — originOverride (D2, chantier « provenance de session », lot 2)', () => {
  test('a conversation created via convo_create on this mount has origin.runtime === "claude-ai", never the server process\'s own Claude Code session env', async () => {
    const client = await connectedClient();
    const id = `test-origin-claude-ai-${Date.now()}`;
    const res = await client.callTool({
      name: 'convo_create',
      arguments: {
        slug: 'workstation',
        id,
        conversation: {
          project: { slug: 'workstation', name: 'Workstation' },
          title: 'Test origine claude-ai',
          items: [{ id: 'q1', kind: 'question', prompt: 'Une question ?' }],
        },
      },
    });
    expect(res.isError).toBeFalsy();

    const onDisk = await getConversation('workstation', id);
    expect(onDisk?.origin?.runtime).toBe('claude-ai');
    expect(onDisk?.origin?.source).toBe('mcp');
    expect(onDisk?.origin?.capturedBy).toBe('explicit');
    // `createdByFromOrigin` maps 'claude-ai' -> 'claude' for the legacy field.
    expect(onDisk?.createdBy).toBe('claude');
    // Constat 4 (revue adversariale) — connexe: a record created via the
    // remote mount must NEVER carry the SERVER PROCESS's own cwd/repoRoot/
    // branch as if it described the remote caller's (there IS no local
    // filesystem for a claude.ai mobile session).
    expect(onDisk?.origin?.cwd).toBeUndefined();
    expect(onDisk?.origin?.repoRoot).toBeUndefined();
    expect(onDisk?.origin?.branch).toBeUndefined();
  });
});

/**
 * D1/D2 (chantier « provenance de session », lot 9) — the READ tools exposed
 * on the REMOTE mount surface `origin` exactly like the local bus (no new
 * field: `origin` is on `ConversationSchema`/`ConversationMetaSchema` since
 * lot 1, on `ChipSchema` since lot 1 and `ChipMetaSchema` since lot 8). This
 * locks that exposure through a REAL `createRemoteServer()` round-trip, not
 * just the local `createServer()` bus already covered by
 * `hubReadTools.test.ts`.
 */
describe('origin exposure on the remote mount (convo_read/convo_list/chips_list/chip_read) — lot 9', () => {
  test('convo_read and convo_list expose origin.runtime === "claude-ai" (originOverride) through createRemoteServer()', async () => {
    const client = await connectedClient();
    const id = `test-origin-read-remote-${Date.now()}`;
    await client.callTool({
      name: 'convo_create',
      arguments: {
        slug: 'workstation',
        id,
        conversation: {
          project: { slug: 'workstation', name: 'Workstation' },
          title: 'Test lecture origine distante',
          items: [{ id: 'q1', kind: 'question', prompt: 'Une question ?' }],
        },
      },
    });

    const readRes = await client.callTool({ name: 'convo_read', arguments: { slug: 'workstation', id } });
    const readOut = JSON.parse((readRes.content as { type: 'text'; text: string }[])[0].text) as {
      conversation: {
        origin?: { runtime: string; capturedBy: string; source?: string; cwd?: string; repoRoot?: string; branch?: string };
      };
    };
    expect(readOut.conversation.origin?.runtime).toBe('claude-ai');
    expect(readOut.conversation.origin?.capturedBy).toBe('explicit');
    // Constat 4 (revue adversariale, chantier « provenance de session »):
    // `convo_read` on the REMOTE mount projects `origin` onto
    // `ReducedOriginSchema` — `source`/`cwd`/`repoRoot`/`branch`/
    // `hostSessionId`/`entrypoint` must never reach a remote caller, even
    // though the local stdio bus (`hubReadTools.test.ts`) exposes them all.
    expect(readOut.conversation.origin?.source).toBeUndefined();
    expect(readOut.conversation.origin?.cwd).toBeUndefined();
    expect(readOut.conversation.origin?.repoRoot).toBeUndefined();
    expect(readOut.conversation.origin?.branch).toBeUndefined();

    const listRes = await client.callTool({ name: 'convo_list', arguments: { slug: 'workstation' } });
    const listOut = JSON.parse((listRes.content as { type: 'text'; text: string }[])[0].text) as {
      conversations: { id: string; origin?: { runtime: string } }[];
    };
    const convo = listOut.conversations.find((c) => c.id === id);
    expect(convo?.origin?.runtime).toBe('claude-ai');
  });
