"""/** Top-level directories of this macOS machine (and the usual Unix ones). */
const LOCAL_ROOTS =
  'Users|home|private|var|tmp|Volumes|opt|root|Applications|Library|System|etc|usr|bin|sbin|cores|dev|mnt|Network';

/** A string that IS a local absolute path, optionally as a `file://` URL —
 *  whole string (spaces allowed: `/Applications/Visual Studio Code.app`),
 *  not a path mentioned inside a sentence. */
const LOCAL_ABSOLUTE_PATH = new RegExp(`^(?:file://)?(?:~|/(?:${LOCAL_ROOTS}))(?:/[^\\\\n]*)?$`);

/** A local path token INSIDE a text (an error message): stops at whitespace,
 *  quotes and closing brackets. */
const LOCAL_PATH_IN_TEXT = new RegExp(`(?:file://)?(?:~|/(?:${LOCAL_ROOTS}))(?:/[^\\\\s'"\\`)\\\\]]*)?(?=$|[\\\\s'"\\`)\\\\],;:])`, 'g');

