9	 * a local absolute path is dropped (a `project.path`, a project state's
10	 * `doc.path`) or cut down to its basename (an attachment `href`, a string in a
11	 * loose record). Free text (prompts, bodies, answers, memory text) is content
12	 * the user wrote and is left untouched. The local stdio surface never calls
13	 * anything here.
14	 */
15	import path from 'node:path';
16	
17	/** Top-level directories of this macOS machine (and the usual Unix ones). */
18	const LOCAL_ROOTS =
19	  'Users|home|private|var|tmp|Volumes|opt|root|Applications|Library|System|etc|usr|bin|sbin|cores|dev|mnt|Network';
20	
21	/** A string that IS a local absolute path, optionally as a `file://` URL —
22	 *  whole string (spaces allowed: `/Applications/Visual Studio Code.app`),
23	 *  not a path mentioned inside a sentence. */
24	const LOCAL_ABSOLUTE_PATH = new RegExp(`^(?:file://)?(?:~|/(?:${LOCAL_ROOTS}))(?:/[^\\n]*)?$`);
25	
26	/** A local path token INSIDE a text (an error message): stops at whitespace,
27	 *  quotes and closing brackets. */
28	const LOCAL_PATH_IN_TEXT = new RegExp(`(?:file://)?(?:~|/(?:${LOCAL_ROOTS}))(?:/[^\\s'"\`)\\]]*)?(?=$|[\\s'"\`)\\],;:])`, 'g');
29	
30	export function isLocalAbsolutePath(value: string): boolean {
31	  return LOCAL_ABSOLUTE_PATH.test(value);
32	}
33	
34	/** Every local path token inside `text` cut to its basename —
35	 *  `EEXIST: mkdir '/var/folders/…/conversations/x'` → `EEXIST: mkdir 'x'`.
36	 *  For error messages the remote surface returns (middleware `errorFilter`),
37	 *  never for user-authored content. */
38	export function redactLocalPathsInText(text: string): string {
39	  return text.replace(LOCAL_PATH_IN_TEXT, (token) => path.basename(token));
40	}
41	
42	/** `/Users/…/docs/roadmap.html` → `roadmap.html`; any other string unchanged. */
43	export function redactLocalPath(value: string): string {
44	  return isLocalAbsolutePath(value) ? path.basename(value) : value;
45	}
46	
47	/** Deep copy of `value` where every string that is a local absolute path is
48	 *  cut down to its basename (`redactLocalPath`). For loose records whose
49	 *  shape is not known in advance (`meta`, a project state's `surfaces`…). */

